import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene transform
  const position = config.scenePosition || [0, 3, 0];
  const rotation = config.sceneRotation || [0, 0, 0];
  const scale = config.sceneScale || [1, 1, 1];

  group.position.set(position[0], position[1], position[2]);
  group.rotation.set(rotation[0], rotation[1], rotation[2]);
  group.scale.set(scale[0], scale[1], scale[2]);

  // Plane dimensions from atlas region (512x320)
  const planeWidth = 5.0;
  const planeHeight = planeWidth * (320 / 512);

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load image texture
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create MeshBasicNodeMaterial
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    depthWrite: false,
  });

  const planeMesh = new THREE.Mesh(geometry, material);
  group.add(planeMesh);

  // Render text content via fontAtlas
  if (config.textContent && ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createText({
      text: config.textContent,
      font: 'JetBrains Mono',
      size: 0.31,
      weight: 400,
      color: new THREE.Color('#e8ecf2'),
    });

    if (textMesh) {
      const padding = 0.25;
      textMesh.position.set(
        -planeWidth / 2 + padding,
        planeHeight / 2 - padding,
        0.01
      );
      group.add(textMesh);
    }
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  group.userData.handlers = {};

  return group;
}
